-- Auth hardening (ADR-001 §6 follow-ups; T-AUTH-006, 012, 013).

-- Generated by prisma migrate diff (the test-only table app.bakeoff_audit_fault is deliberately not touched).
ALTER TABLE "app"."app_user" ADD COLUMN     "second_factor_failures" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "second_factor_locked_until" TIMESTAMPTZ;

-- ---------- Hand-written ----------
grant update (second_factor_failures, second_factor_locked_until) on app.app_user to gems_auth;

-- Idle timeout in minutes. PMC (D-SEC-3); must equal POLICY.idleMinutes in src/server/auth/policy.ts (a test checks).
create function app.idle_minutes() returns int language sql immutable as $$ select 30 $$;

-- One rule for "may this account act at all" (T-AUTH-011, T-AUTH-012):
-- active user, holding at least one assignment that is either wider than a centre or on an ACTIVE centre.
-- Staff of a deactivated centre are locked out; HO users with region/area/all scope keep access (history stays visible).
create function app.account_usable(p_user uuid) returns boolean
language sql stable security definer
set search_path = pg_catalog, app
as $$
  select exists (
    select 1
    from app.app_user u
    join app.role_assignment ra on ra.user_id = u.id
    left join app.centre c on c.id = ra.scope_centre_id
    where u.id = p_user and u.status = 'ACTIVE'
      and (ra.scope_kind <> 'CENTRE' or c.status = 'ACTIVE'))
$$;
revoke all on function app.account_usable(uuid) from public;
grant execute on function app.account_usable(uuid) to gems_auth;

-- The session the RLS layer trusts: now also enforces the idle timeout and account_usable in the database,
-- so a request that skips the app-level resolve() still cannot use an idle session (T-AUTH-013).
create or replace function app.session_user_id() returns uuid
language sql stable security definer
set search_path = pg_catalog, app
as $$
  select s.user_id
  from app.app_session s
  where s.token_hash = sha256(convert_to(nullif(current_setting('app.session_id', true), ''), 'UTF8'))
    and s.revoked_at is null
    and s.expires_at > now()
    and s.last_seen_at > now() - make_interval(mins => app.idle_minutes())
    and app.account_usable(s.user_id)
$$;
